  export WINEPREFIX="$PREFIX_ROOT"
  export STEAM_COMPAT_DATA_PATH="$(dirname "$PREFIX_ROOT")"
elif [[ -d "$PREFIX_ROOT/pfx" ]]; then
  export WINEPREFIX="$PREFIX_ROOT/pfx"
